import { test, expect } from '@playwright/test';

test.describe('Past Date Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="dateForm">
        <label for="pastDate">Select a Past Date:</label>
        <input 
          type="date" 
          id="pastDate" 
          name="pastDate"
          required
        />
        <button type="submit">Submit</button>
        <div id="errorMessage" style="color: red; display: none;"></div>
      </form>
      <script>
        const form = document.getElementById('dateForm');
        const pastDateInput = document.getElementById('pastDate');
        const errorMessage = document.getElementById('errorMessage');

        form.addEventListener('submit', (e) => {
          e.preventDefault();
          errorMessage.style.display = 'none';
          errorMessage.textContent = '';

          const selectedDate = new Date(pastDateInput.value);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          if (selectedDate > today) {
            errorMessage.textContent = 'Error: Please select a date in the past.';
            errorMessage.style.display = 'block';
          } else {
            errorMessage.textContent = 'Form submitted successfully!';
            errorMessage.style.display = 'block';
            errorMessage.style.color = 'green';
          }
        });
      </script>
    `);
  });

  test('should display error when submitting form with future date in past-date field', async ({ page }) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowString = tomorrow.toISOString().split('T')[0];

    const dateInput = page.getByLabel('Select a Past Date:');
    await dateInput.fill(tomorrowString);

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Error: Please select a date in the past.');
  });

  test('should not display error when submitting form with past date', async ({ page }) => {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayString = yesterday.toISOString().split('T')[0];

    const dateInput = page.getByLabel('Select a Past Date:');
    await dateInput.fill(yesterdayString);

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Form submitted successfully!');
    await expect(errorMessage).toHaveCSS('color', 'rgb(0, 128, 0)');
  });

  test('should display error when submitting form with today date in past-date field', async ({ page }) => {
    const today = new Date();
    const todayString = today.toISOString().split('T')[0];

    const dateInput = page.getByLabel('Select a Past Date:');
    await dateInput.fill(todayString);

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Error: Please select a date in the past.');
  });

  test('should clear error message when correcting the date after initial error', async ({ page }) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tomorrowString = tomorrow.toISOString().split('T')[0];

    const dateInput = page.getByLabel('Select a Past Date:');
    await dateInput.fill(tomorrowString);

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toContainText('Error: Please select a date in the past.');

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const yesterdayString = yesterday.toISOString().split('T')[0];

    await dateInput.fill(yesterdayString);
    await submitButton.click();

    await expect(errorMessage).toContainText('Form submitted successfully!');
    await expect(errorMessage).toHaveCSS('color', 'rgb(0, 128, 0)');
  });
});
